/**
 * 认知扩展阶段 B / M4：记忆工具面。
 *
 * 不变量：模型只见 ID 与 query，不见路径、subjectId 或其他主体的任何标识。
 * - 工具 schema 中不存在 subjectId/路径参数——隔离边界由构造注入，不给模型留口子；
 * - scope 由绑定上下文注入（当前实现：主体默认作用域），不从模型参数读；
 * - 服务层 committed/conflict/rejected 适配为真实工具五态：
 *   committed → succeeded；conflict/rejected → failed（版本冲突不报告"记住了"）；
 *   写入抛异常 → unknown（不猜测未确认结果）。
 */

import type { Tool } from "../../tools/broker.js";
import {
	createMemoryStore,
	type MemoryStore,
	type MemoryStoreOptions,
	type MemoryChange,
} from "./memory.js";

export { createMemoryStore, type MemoryStore, type MemoryStoreOptions, type MemoryChange } from "./memory.js";

/** 服务层三态 → 工具五态的正文承载：JSON 字符串，模型可解析 hash/当前版本。 */
function adaptResult(id: string | undefined, result: Awaited<ReturnType<MemoryStore["write"]>>): { result: string; status: "succeeded" | "failed" } {
	if (result.status === "committed") {
		return {
			result: JSON.stringify({ status: "committed", id: result.id, hash: result.hash, revision: result.revision }, null, "\t"),
			status: "succeeded",
		};
	}
	return {
		result: JSON.stringify({ status: result.status, ...(id ? { id } : {}), ...(result.status === "conflict" ? { currentHash: result.currentHash } : {}), reason: result.reason }, null, "\t"),
		status: "failed",
	};
}

/**
 * 认知能力工厂：由 Host/测试以绑定资源装配。
 * 记忆工具可操作的范围由绑定上下文决定——这是唯一合法的路径/主体来源。
 */
export interface CognitionCapabilityOptions extends MemoryStoreOptions {
	memoryStore?: MemoryStore;
}

export function createCognitionCapability(options: CognitionCapabilityOptions): { store: MemoryStore; tools: Tool[] } {
	const store = options.memoryStore ?? createMemoryStore(options);
	return { store, tools: createMemoryTools(store) };
}

/** 由 MemoryStore 构造三工具。store 的绑定已封闭，工具 schema 无身份参数。 */
export function createMemoryTools(store: MemoryStore): Tool[] {
	const memorySearch: Tool = {
		def: {
			type: "function",
			function: {
				name: "memory_search",
				description:
					"在当前主体的长期记忆中检索。返回命中的记忆 ID、标题、摘要与版本提示；需要完整内容时用 memory_read。只检索当前绑定主体与作用域，不涉及其他个体。",
				parameters: {
					type: "object",
					properties: {
						query: { type: "string", description: "检索关键词或片段（支持中文，无需分词）" },
					},
					required: ["query"],
					additionalProperties: false,
				},
			},
		},
		async run(args) {
			const query = String(args.query ?? "");
			const hits = await store.search(query, {});
			if (hits.length === 0) {
				return { result: JSON.stringify({ hits: [] }), status: "succeeded" };
			}
			return {
				result: JSON.stringify(
					{
						hits: hits.map((h) => ({ id: h.id, title: h.title, excerpt: h.excerpt, revision: h.revision, hash: h.hash })),
					},
					null,
					"\t",
				),
				status: "succeeded",
			};
		},
	};

	const memoryRead: Tool = {
		def: {
			type: "function",
			function: {
				name: "memory_read",
				description: "读取一条长期记忆的当前完整内容（正文、来源与适用范围）。id 来自 memory_search 或 memory_write 的返回。",
				parameters: {
					type: "object",
					properties: {
						id: { type: "string", description: "记忆 ID（memory_search 返回的 id）" },
					},
					required: ["id"],
					additionalProperties: false,
				},
			},
		},
		async run(args) {
			const id = String(args.id ?? "");
			const record = await store.read(id);
			if (!record) {
				return { result: JSON.stringify({ error: `记忆不存在或已遗忘：${id}` }), status: "failed" };
			}
			return {
				result: JSON.stringify(
					{
						id: record.id,
						title: record.title,
						body: record.body,
						type: record.type,
						basis: record.basis,
						scope: record.scope,
						sources: record.sources,
						status: record.status,
						revision: record.revision,
						hash: record.hash,
					},
					null,
					"\t",
				),
				status: "succeeded",
			};
		},
	};

	const memoryWrite: Tool = {
		def: {
			type: "function",
			function: {
				name: "memory_write",
				description:
					"写入/修订/退休一条长期记忆。create 需 type/basis/title/body/scope/sources（或 basis=inferred + rationale）；revise/retire 需要当前 hash（从 memory_read 获得）。返回 committed 时携带新 hash——后续修订必须使用新 hash。版本冲突不覆盖：返回 conflict 与当前 hash，需重新读取后决定。",
				parameters: {
					type: "object",
					properties: {
						operation: {
							type: "object",
							description: "记忆变更操作",
							oneOf: [
								{
									type: "object",
									properties: {
										op: { type: "string", const: "create" },
										record: {
											type: "object",
											properties: {
												type: { type: "string", enum: ["note", "commitment", "procedure"] },
												basis: { type: "string", enum: ["observed", "reported", "inferred"] },
												title: { type: "string" },
												body: { type: "string" },
												scope: { type: "object", properties: { spaceId: { type: "string" }, projectId: { type: "string" }, actorId: { type: "string" } }, additionalProperties: false },
												sources: { type: "array", items: { type: "object", properties: { sessionId: { type: "string" }, entryId: { type: "string" }, note: { type: "string" } }, required: ["sessionId"], additionalProperties: false } },
												rationale: { type: "string" },
												pinned: { type: "boolean" },
											},
											required: ["type", "basis", "title", "body", "scope", "sources", "pinned"],
											additionalProperties: false,
										},
									},
									required: ["op", "record"],
									additionalProperties: false,
								},
								{
									type: "object",
									properties: {
										op: { type: "string", const: "revise" },
										id: { type: "string" },
										expectedHash: { type: "string" },
										record: {
											type: "object",
											properties: {
												title: { type: "string" },
												body: { type: "string" },
												scope: { type: "object", properties: { spaceId: { type: "string" }, projectId: { type: "string" }, actorId: { type: "string" } }, additionalProperties: false },
												sources: { type: "array", items: { type: "object", properties: { sessionId: { type: "string" }, entryId: { type: "string" }, note: { type: "string" } }, required: ["sessionId"], additionalProperties: false } },
												rationale: { type: "string" },
												pinned: { type: "boolean" },
											},
											additionalProperties: false,
										},
									},
									required: ["op", "id", "expectedHash", "record"],
									additionalProperties: false,
								},
								{
									type: "object",
									properties: {
										op: { type: "string", const: "retire" },
										id: { type: "string" },
										expectedHash: { type: "string" },
										reason: { type: "string" },
									},
									required: ["op", "id", "expectedHash", "reason"],
									additionalProperties: false,
								},
							],
						},
					},
					required: ["operation"],
					additionalProperties: false,
				},
			},
		},
		async run(args) {
			const operation = args.operation as MemoryChange;
			if (!operation || typeof operation !== "object" || !("op" in operation)) {
				return { result: JSON.stringify({ status: "rejected", reason: "缺少 operation" }), status: "failed" };
			}
			const id = "id" in operation ? String(operation.id) : undefined;
			try {
				const result = await store.write(operation);
				return adaptResult(id, result);
			} catch (error) {
				// writer 内部异常：不猜测结果（unknown），明确上报。
				return {
					result: JSON.stringify({ status: "unknown", ...(id ? { id } : {}), reason: `写入未确认，请用 memory_read 核实后再试：${String(error)}` }),
					status: "unknown",
				};
			}
		},
	};

	return [memorySearch, memoryRead, memoryWrite];
}

/**
 * 认知扩展阶段 C / M5：最小召回与瞬态记忆块（+ cognition 能力激活入口）。
 *
 * 不变量：
 * 1. 自动召回确定性：取最新 user 输入文本 → 字符片段匹配，绝不调用模型；
 * 2. 无关不注入：无命中返回 undefined，不输出空模板；
 * 3. 注入量受预算约束（估算 token：CJK ≈1 token/字，其余 ≈1 token/4 字节）；
 *    pinned 优先，超预算跳过——不截断单条正文（截断会制造假记忆），不突破预算；
 * 4. 注入块是带标注的内部信息块（user 角色），不拼成更高权威的 system 事实；
 * 5. 注册为非 tail transformContext（备忘 §3.1：记忆线索必须在尾帧之前，
 *    否则被瞬态视口/具身帧稀释，且破坏层序合同）；
 * 6. scope 由 Host 绑定注入（pi.subject），不从模型参数读；
 * 7. pi.subject 缺失时激活明确失败——不静默降级（静默降级会伪装成隔离成功）。
 */

import type { ExtensionAPI } from "../runner.js";
import { createMemoryStore, type MemoryStore, type MemoryHit } from "./memory.js";
import { createMemoryTools } from "./index.js";

const RECALL_LABEL = "[记忆线索]";
export const DEFAULT_MEMORY_BUDGET_TOKENS = 1200;

/** 估算一段文本的 token 数：CJK 字符 ≈ 1 token/字，其余 ≈ 1 token/4 字节。 */
export function estimateTokens(text: string): number {
	let cjk = 0;
	for (const ch of text) {
		if (/[\u3000-\u9FFF\uF900-\uFA6D]/.test(ch)) cjk++;
	}
	return cjk + Math.ceil((text.length - cjk) / 4);
}

type MinimalMessage = { role: string; content: unknown };

export interface ContextInjectorOptions {
	store: MemoryStore;
	scope: { spaceId?: string; projectId?: string; actorId?: string };
	/** 注入预算（估算 token）。 */
	budgetTokens?: number;
}

/**
 * 构造上下文注入器（纯函数形态，便于单测）。
 * 输入模型请求消息数组；输出带注入块的新数组（原数组不被修改），无命中时 undefined。
 */
export function createContextInjector(options: ContextInjectorOptions) {
	const { store, scope } = options;
	const budget = options.budgetTokens ?? DEFAULT_MEMORY_BUDGET_TOKENS;

	return async function injector(messages: readonly MinimalMessage[]): Promise<{ messages: MinimalMessage[] } | undefined> {
		// 确定性召回输入：最新一条 user 文本。绝不调用模型生成查询。

[文件共 139 行，当前显示到第 50 行。用 offset=51 继续读。]

		let query = "";
		for (let i = messages.length - 1; i >= 0; i--) {
			if (messages[i]!.role === "user") {
				const content = messages[i]!.content;
				query = typeof content === "string" ? content : JSON.stringify(content);
				break;
			}
		}
		if (!query.trim()) return undefined;

		const hits = await store.search(query, scope);
		if (hits.length === 0) return undefined;

		// pinned 优先，其余按检索分；超预算整条跳过。
		const ordered = [...hits].sort((a, b) => Number(b.pinned) - Number(a.pinned) || b.score - a.score);
		const lines: string[] = [];
		let used = 0;
		for (const hit of ordered) {
			const line = formatHit(hit);
			const cost = estimateTokens(line) + 4;
			if (used + cost > budget) continue;
			lines.push(line);
			used += cost;
		}
		if (lines.length === 0) return undefined;

		const block = [
			`${RECALL_LABEL}（来自本主体长期记忆；内部信息而非用户原话，可质疑、可修订，引用时注明来源）`,
			...lines,
		].join("\n");
		return { messages: [...messages, { role: "user", content: block }] };
	};
}

function formatHit(hit: MemoryHit): string {
	const pin = hit.pinned ? " [锚点]" : "";
	return `- [${hit.id} rev${hit.revision}${pin}] ${hit.title}：${hit.excerpt}`;
}

/**
 * cognition 能力激活入口（Host 内置装配用，阶段 B+C 合并接线）：
 * - pi.subject 缺失 → 明确抛错（仅 profile 模式激活）；
 * - 注册三工具（M4）+ 非 tail transformContext 召回注入（M5）；
 * - 来源校验绑定当前会话：entryId 必须能在本会话历史中读到；
 * - scope 第一版取主体全局（Host 仅 default session；接入层多 session 到达时
 *   由 Host 传入当前上下文，不从模型文本猜测）。
 */
export function activateCognition(pi: ExtensionAPI): void {
	if (!pi.subject) {
		throw new Error("cognition 需要 subject 绑定（pi.subject）；仅 profile 模式可激活，不做静默降级。");
	}
	const subject = pi.subject;

	// 身份与路径都是 Host 已知事实，显式绑定传入——不从路径推断身份。
	const store = createMemoryStore({
		subjectId: subject.subjectId,
		memoryRoot: subject.memoryRoot,
		stateRoot: subject.stateRoot,
		sessionId: subject.sessionId,
		validateSource: async (ref) => {
			if (ref.sessionId !== subject.sessionId) return false;
			if (!ref.entryId) return true;
			try {
				void pi.session.read(ref.entryId);
				return true;
			} catch {
				return false;
			}
		},
	});

	// M4：三工具。
	for (const tool of createMemoryTools(store)) pi.registerTool(tool);

	// M5：非 tail transformContext（默认注册即非 tail；尾相位留给视口/具身瞬态帧）。
	// injector 在激活时构造一次（闭包只依赖 store/scope，无需每请求重建）；
	// hook handler 只生成新的 RequestProjection，不修改传入投影。
	const injector = createContextInjector({ store, scope: {} });
	pi.onHook("turn.transformContext", async (projection) => {
		const result = await injector(projection.messages as unknown as readonly MinimalMessage[]);
		if (!result) return undefined;
		return { projection: { ...projection, messages: result.messages as import("../../core/types.js").ChatMsg[] } };
	});

	// 生命周期：scope 关闭时等待在途写结算（此后写入明确拒绝——store.close 硬合同）。
	pi.signal.addEventListener("abort", () => {
		void store.close();
	});
}

